    vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
    vec3& operator/=(double s) { x /= s; y /= s; z /= s; return *this; }

    double length() const { return std::sqrt(x * x + y * y + z * z); }
    double lengthSquared() const { return x * x + y * y + z * z; }

    vec3 normalized() const {
        double len = length();
        return (len > 0) ? (*this / len) : vec3(0, 0, 0);
